#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxSameLengthRuns(string s) {
        vector<int> count(s.size()+1,0);
        int ans = 0;
        for (int i = 0, j; i < (int)s.size(); i = j) {
            j = i + 1;
            while (j < (int)s.size() && s[j] == s[i]) ++j;
            ans = max(ans, ++count[j-i]);
        }
        return ans;
    }
};
